# compat.sh — the same moves done by repo-mv.sh and by csm on two equal
# trees must leave equal trees. The data avoids the differences that
# prompt.md (4.0) allows, and .claude.json is compared after jq -S, as the
# script lets jq lay it out anew.
#
# Usage: compat.sh CSM REPO_MV WORKDIR

CSM=$(cd "$(dirname "$1")" && pwd)/$(basename "$1")
SCRIPT=$2
WORK=$(cd "$3" && pwd -P)
CHECKS=0
FAILURES=0

for TOOL in zsh perl jq
do
	if ! command -v "$TOOL" > /dev/null 2>&1
	then
		echo "compat: skipped, as $TOOL is missing."
		exit 0
	fi
done
if [ ! -f "$SCRIPT" ]
then
	echo "compat: skipped, as $SCRIPT is missing (it lives outside git)."
	exit 0
fi
SCRIPT=$(cd "$(dirname "$SCRIPT")" && pwd)/$(basename "$SCRIPT")

LC_ALL=en_US.UTF-8
CSM_CLAUDE_PROCESS=csm-no-such-process
R=$WORK/run
HOME=$R/home
CLAUDE_CONFIG_DIR=$HOME/.claude
PROJ=$CLAUDE_CONFIG_DIR/projects
export LC_ALL CSM_CLAUDE_PROCESS HOME CLAUDE_CONFIG_DIR

# The script stops while Claude Code runs; its pgrep finds nothing here.
# Its mktemp files stay in WORK: macOS mktemp without a template ignores
# TMPDIR, and the Claude Code sandbox does not let it write elsewhere.
mkdir -p "$WORK/bin" "$WORK/tmp"
printf '#!/bin/sh\nexit 1\n' > "$WORK/bin/pgrep"
printf '#!/bin/sh\nexec %s "%s/tmp/tmp.XXXXXX"\n' "$(command -v mktemp)" \
    "$WORK" > "$WORK/bin/mktemp"
chmod 755 "$WORK/bin/pgrep" "$WORK/bin/mktemp"

enc() {
	printf '%s' "$1" | LC_ALL=C sed 's/[^A-Za-z0-9]/-/g'
}

session() {
	FILE=$1
	shift
	mkdir -p "$(dirname "$FILE")"
	printf '{"type":"permission-mode","permissionMode":"default"}\n' > "$FILE"
	for CWD in "$@"
	do
		printf '{"type":"user","cwd":"%s","n":1}\n' "$CWD" >> "$FILE"
	done
}

# The same data at the same place for both runs.
make_tree() {
	rm -rf "$R"
	mkdir -p "$R/a/repo/sub" "$R/a/repo2" "$R/b" "$R/m/old" "$R/f/old"
	mkdir -p "$R/Mobile Documents/Dev/repo" "$PROJ"
	ln -s "Mobile Documents/Dev" "$R/Dev"

	P=$PROJ/$(enc "$R/a/repo")
	session "$P/s1.jsonl" "$R/a/repo" "$R/a/repo/sub" /elsewhere
	session "$P/s1/subagents/agent-1.jsonl" "$R/a/repo/sub"
	mkdir -p "$P/memory"
	echo note > "$P/memory/MEMORY.md"
	printf '{"version":1,"entries":[{"fullPath":"%s/s1.jsonl","projectPath":"%s"}],"originalPath":"%s"}\n' \
	    "$P" "$R/a/repo" "$R/a/repo" > "$P/sessions-index.json"
	session "$PROJ/$(enc "$R/a/repo/sub")/s2.jsonl" "$R/a/repo/sub"
	session "$PROJ/$(enc "$R/a/repo2")/s3.jsonl" "$R/a/repo2"

	session "$PROJ/$(enc "$R/Dev/repo")/l.jsonl" "$R/Dev/repo"
	session "$PROJ/$(enc "$R/Mobile Documents/Dev/repo")/p.jsonl" \
	    "$R/Mobile Documents/Dev/repo"

	session "$PROJ/$(enc "$R/m/old")/o.jsonl" "$R/m/old"
	session "$PROJ/$(enc "$R/m/new")/n.jsonl" "$R/m/new"

	session "$PROJ/$(enc "$R/f/old")/f.jsonl" "$R/f/old"

	printf '{"numStartups":3,"projects":{"%s":{"allowedTools":[]},"%s":{},"%s":{"t":1},"%s":{},"%s":{}},"other":"x"}\n' \
	    "$R/a/repo" "$R/a/repo2" "$R/Dev/repo" "$R/m/old" "$R/f/old" \
	    > "$CLAUDE_CONFIG_DIR/.claude.json"
}

# do_moves MOVE FIX — the scenario, with the tool's move and fix commands.
do_moves() {
	(cd "$R" && $1 a/repo b) &&
	    (cd "$R/Dev" && $1 repo moved) &&
	    (cd "$R" && $1 m/old m/new) &&
	    mv "$R/f/old" "$R/f/new" &&
	    (cd "$R" && $2 f/old f/new)
}

script_move() {
	PATH=$WORK/bin:$PATH zsh "$SCRIPT" "$@"
}

script_fix() {
	PATH=$WORK/bin:$PATH zsh "$SCRIPT" -s "$@"
}

csm_move() {
	"$CSM" -m "$@"
}

csm_fix() {
	"$CSM" -F "$@"
}

# Names and contents of the tree; JSON configuration in jq's sorted form.
snapshot() {
	for FILE in "$1/home/.claude/.claude.json" "$1/home/.claude/.claude.json.bak"
	do
		jq -S . "$FILE" > "$FILE.sorted" && mv "$FILE.sorted" "$FILE"
	done
	(cd "$1" && find . -print | LC_ALL=C sort &&
	    find . -type f -exec cksum {} + | LC_ALL=C sort)
}

check() {
	CHECKS=$((CHECKS + 1))
	if ! "$@"
	then
		FAILURES=$((FAILURES + 1))
		return 1
	fi
}

make_tree
if ! check do_moves script_move script_fix > "$WORK/script.out" 2>&1
then
	echo "compat: repo-mv.sh failed: $(cat "$WORK/script.out")"
fi
rm -rf "$WORK/script"
mv "$R" "$WORK/script"

make_tree
if ! check do_moves csm_move csm_fix > "$WORK/csm.out" 2>&1
then
	echo "compat: csm failed: $(cat "$WORK/csm.out")"
fi

# Both trees sit at the same place in turn, so the paths inside agree.
snapshot "$R" > "$WORK/csm.tree"
rm -rf "$WORK/csm"
mv "$R" "$WORK/csm"
mv "$WORK/script" "$R"
snapshot "$R" > "$WORK/script.tree"
mv "$R" "$WORK/script"
if ! check cmp -s "$WORK/script.tree" "$WORK/csm.tree"
then
	echo "compat: trees differ (< repo-mv.sh, > csm):"
	diff "$WORK/script.tree" "$WORK/csm.tree" | head -40
fi

echo "compat: $CHECKS checks, $FAILURES failed"
[ "$FAILURES" -eq 0 ]
